// ================================================================ number helpers
// C float -> uint32 on the Cortex-M7: truncate, negative and NaN -> 0, saturate at the top
function f2u(x) {
	if (x > 0) {
		if (x >= 4294967295) return 4294967295;
		return trunc(x);
	}
	return 0;
}

function wrap32(x) {
	return x - TWO32 * floor(x / TWO32);
}

function wrap16(x) {
	return x - 65536 * floor((x + 32768) / 65536);
}

function sat16(x) {
	if (x > 32767) return 32767;
	if (x < -32768) return -32768;
	return x;
}

// C float -> int16_t: truncate, keep the low 16 bits
function i16(x) {
	return wrap16(trunc(x));
}

// __SSAT(x, 16) of a float argument
function ssat(x) {
	return sat16(trunc(x));
}

// fr(): round to the nearest C float (Veltkamp split: 53 - 29 = 24 significant bits).
// The firmware computes in single precision, and where a result is truncated to an
// integer (16-bit samples, phase offsets) the float rounding decides the last step.
function fr(x) {
	let c = x * 536870913;
	return c - (c - x);
}

// round to IEEE half precision (the delay line stores __fp16)
function f16(x) {
	if (abs(x) < 0.00006103515625) return floor(x * 16777216 + 0.5) / 16777216;
	let c = x * 4398046511105;
	return c - (c - x);
}

function clamp01(x) {
	if (x < 0) return 0;
	if (x > 1) return 1;
	return x;
}

// k = 2s/(1-s) waveshaper used for envelope curves and parameter scaling
function egCurve(val, slope) {
	return (1 + slope) * val / (1 + slope * abs(val));
}

// valueShaperF2F (float maths)
function valueShaper(val, shape) {
	let k = fr(fr(2 * shape) / fr(1.000100016593933 - shape));
	return fr(fr(fr(1 + k) * val) / fr(1 + fr(k * abs(val))));
}

// Stand-in for the hardware RNG: one 32-bit LCG per noise source (the same streams as
// the C reference build uses), halves swapped so the low 16 bits are well mixed.
function rng32(k) {
	let s = wrap32(rngS[k] * 1664525 + 1013904223);
	rngS[k] = s;
	let hi = floor(s / 65536);
	let lo = s - hi * 65536;
	return lo * 65536 + hi;
}

// (int16_t)GetRngValue()
function rng16(k) {
	let r = rng32(k);
	let lo = r - 65536 * floor(r / 65536);
	if (lo >= 32768) return lo - 65536;
	return lo;
}

// ================================================================ oscillators
function mainOsc(v) {
	if (v < 3) return 2 * v;
	if (v == 3) return 6;
	if (v == 4) return 8;
	return 11;
}

// which of the 11 band-limited tables to use (freqToTableIndex incl. its uint8 quirk:
// everything below 440 Hz lands on table 4)
function tableIndex(f) {
	let v = f2u(fr(f / 440));
	if (v < 1) return 4;
	let l = 0;
	for (let k = 0; k < 32; k++) {
		if (v < 2) break;
		v = floor(v / 2);
		l = l + 1;
	}
	return min(10, l + 5);
}

function oscSetFreq(o) {
	let f = fr(oFreq[o] * oPitch[o]);
	let w = oWave[o];
	if (w == W_SINE || w == W_NOISE) {
		oInc[o] = f2u(fr(4096 * f / fsr) * 1048576);
	} else if (w <= W_PWM) {
		oInc[o] = f2u(fr(1024 * f / fsr) * 4194304);
		oTbl[o] = tableIndex(f);
	} else {
		oInc[o] = f2u(fr(1024 * f / fsr) * 131072);
	}
}

function oscRecalc(o) {
	let cent = fr(1 + fr(fr(fr(oFine[o] / 127) - 0.5) * 0.05946314334869385));
	let n = oCoarse[o] + oBase[o] - 60;
	if (n > 127) n = 127;
	if (n < 0) n = 0;
	oFreq[o] = fr(NOTEF[n] * cent);
}

function oscBase(o, note) {
	oBase[o] = note;
	oscRecalc(o);
}

function sineAt(index) {
	let itg = floor(index / 1048576);
	let a = SINE[itg];
	return a + floor((SINE[itg + 1] - a) * (index - itg * 1048576) / 1048576);
}

function wtAt(base, index) {
	let itg = floor(index / 4194304);
	let a = WT[base + itg];
	return a + floor((WT[base + itg + 1] - a) * (index - itg * 4194304) / 4194304);
}

// calcNoiseBlock: sample and hold white noise, new value on every phase wrap
function noiseBlock(o, dst, gain) {
	let p = oPhase[o];
	let inc = oInc[o];
	for (let i = 0; i < N; i++) {
		p = p + inc;
		if (p >= TWO32) {
			p = p - TWO32;
			oOut[o] = rng16(o);
		}
		SCR[dst + i] = i16(fr(oOut[o] * gain));
	}
	oPhase[o] = p;
}

// phase of the second, shifted saw of the PWM wave: index + pwm * (UINT32_MAX / 2),
// added up in float and saturated at the top
function pwmIndex(index, pw) {
	return f2u(fr(fr(index) + pw * 2147483648));
}

// calcNextOscSampleBlock
function oscBlock(o, dst, gain, pw) {
	let w = oWave[o];
	let p = oPhase[o];
	let inc = oInc[o];
	if (w == W_SINE) {
		for (let i = 0; i < N; i++) {
			SCR[dst + i] = i16(fr(sineAt(p) * gain));
			p = wrap32(p + inc);
		}
	} else if (w <= 3) {
		let base = (w - 1) * WTS + oTbl[o] * 1024;
		for (let i = 0; i < N; i++) {
			SCR[dst + i] = i16(fr(wtAt(base, p) * gain));
			p = wrap32(p + inc);
		}
	} else if (w == W_NOISE) {
		noiseBlock(o, dst, gain);
		return;
	} else if (w == W_PWM) {
		let base = WTS + oTbl[o] * 1024;
		let smp = 0;
		for (let i = 0; i < N; i++) {
			smp = sat16(wtAt(base, p) - wtAt(base, pwmIndex(p, pw)));
			SCR[dst + i] = i16(fr(smp * gain));
			p = wrap32(p + inc);
		}
		oOut[o] = smp;
	}
	// waveforms above PWM were sample playback, disabled in the firmware
	oPhase[o] = p;
}

// calcNextOscSampleFmBlock: phase modulated by the block at modBuf. The modulation
// index is (uint32_t)(int16 * float): rounded to float first, like the firmware, since
// a one-step difference moves the phase by 1/8192 of a cycle.
function oscFmBlock(o, modBuf, dst, gain, pw) {
	let w = oWave[o];
	let p = oPhase[o];
	let inc = oInc[o];
	let fm = oFm[o];
	if (w == W_SINE) {
		for (let i = 0; i < N; i++) {
			let index = wrap32(p + wrap32(f2u(fr(SCR[modBuf + i] * fm)) * 131072));
			SCR[dst + i] = i16(fr(sineAt(index) * gain));
			p = wrap32(p + inc);
		}
	} else if (w <= 3) {
		let base = (w - 1) * WTS + oTbl[o] * 1024;
		let smp = 0;
		for (let i = 0; i < N; i++) {
			let index = wrap32(p + wrap32(f2u(fr(SCR[modBuf + i] * fm)) * 524288));
			smp = wtAt(base, index);
			SCR[dst + i] = i16(fr(smp * gain));
			p = wrap32(p + inc);
		}
		oOut[o] = smp;
	} else if (w == W_NOISE) {
		noiseBlock(o, dst, gain);
		return;
	} else if (w == W_PWM) {
		let base = WTS + oTbl[o] * 1024;
		let smp = 0;
		for (let i = 0; i < N; i++) {
			let index = wrap32(p + wrap32(f2u(fr(SCR[modBuf + i] * fm)) * 524288));
			smp = sat16(wtAt(base, index) - wtAt(base, pwmIndex(index, pw)));
			SCR[dst + i] = i16(fr(smp * gain));
			p = wrap32(p + inc);
		}
		oOut[o] = smp;
	}
	oPhase[o] = p;
}

// ================================================================ building blocks
function qaddBuf(dst, src) {
	for (let i = 0; i < N; i++) SCR[dst + i] = sat16(SCR[dst + i] + SCR[src + i]);
}

// transient_calcBlock
function transBlock(v, dst) {
	let w = trWave[v];
	let ph = trPhase[v];
	if (w <= 1 || ph >= 2311061504) {
		for (let i = 0; i < N; i++) SCR[dst + i] = 0;
		return;
	}
	let base = (w - 2) * TRL;
	let stp = trPitch[v] * 1048576 * kr;
	for (let i = 0; i < N; i++) {
		if (ph < 2311061504) {
			SCR[dst + i] = i16(fr(trVol[v] * (TR[base + floor(ph / 1048576)] * 256)));
			ph = f2u(fr(ph + stp));
		} else {
			SCR[dst + i] = 0;
		}
	}
	trPhase[v] = ph;
}

// SnapEg_calc
function snapCalc(v, tm) {
	let ret = 0;
	if (snap[v] > 0) {
		ret = fr(fr(snap[v] * snap[v]) * 24);
		snap[v] = fr(snap[v] - fr(0.20000000298023224 * tm * kr));
	}
	return ret;
}

// DecayEg_calc (pitch envelope)
function decayCalc(v) {
	let val = peValue[v];
	if (val > 0) val = fr(val - peDecay[v] * kr);
	else val = 0;
	peValue[v] = val;
	let sl = peSlope[v];
	return fr(fr(fr(1 + sl) * val) / fr(1 + fr(sl * abs(val))));
}

// slopeEg2_calc (amp envelope)
function aeCalc(v) {
	let val = aeValue[v];
	let st = aeState[v];
	if (st == EG_STOPPED) return 0;
	if (st == EG_REPEAT) {
		if (val > 0) {
			val = val - aeAttack[v] * kr;
		} else {
			aeRepCnt[v] = aeRepCnt[v] - 1;
			if (aeRepCnt[v] < 0) aeRepCnt[v] = aeRepCnt[v] + 256;
			if (aeRepCnt[v] <= 0) aeState[v] = EG_D;
			val = 1;
		}
		aeValue[v] = val;
		return egCurve(val, aeSlope[v]);
	}
	if (st == EG_A) {
		val = val + aeAttack[v] * kr;
		if (val >= 1) {
			val = 1;
			aeState[v] = EG_D;
		}
		aeValue[v] = val;
		return egCurve(val, aeInv[v]);
	}
	if (st == EG_D) {
		if (val > 0) {
			val = val - aeDecay[v] * kr;
			aeValue[v] = val;
			return egCurve(val, aeSlope[v]);
		}
		aeValue[v] = 0;
	}
	return 0;
}

function aeTrigger(v) {
	if (aeRepeat[v] == 0) {
		aeState[v] = EG_A;
	} else {
		aeState[v] = EG_REPEAT;
		aeValue[v] = 1;
	}
	aeRepCnt[v] = aeRepeat[v];
}

// slopeEg2_calcTime
function egTime(itg, k) {
	let val = itg / 127;
	let ret = fr((1 - (1 + k) * val / (1 + k * abs(val))) * 2);
	if (ret > 1) return 1;
	return ret;
}

// softClipTwo(): in * tanhXdX(0.5 * in), a Pade approximation of tanh
// softClipTwo(): in * tanhXdX(0.5 * in), a Pade approximation of tanh. When the
// filter state runs away the float maths overflows: num / inf = 0, inf / inf = NaN.
// NaN is reported through scNan instead of being produced (it must never reach RNBO).
function softClip(x) {
	let h = fr(0.5 * x);
	let a = fr(h * h);
	let num = fr(fr(fr(a + 105) * a) + 945);
	let den = fr(fr(fr(fr(15 * a) + 420) * a) + 945);
	if (den > FLT_MAX) {
		if (num > FLT_MAX) scNan = 1;
		return 0;
	}
	return fr(x * fr(num / den));
}

function fastTanh(x) {
	if (x < -1.9500000476837158) return -1;
	if (x > 1.9500000476837158) return 1;
	return fr(fr(4.150000095367432 * x) / fr(4.289999961853027 + fr(x * x)));
}

function fastTan(x) {
	let x2 = fr(x * x);
	return fr(fr(fr(-15 * x) + fr(x * x2)) / fr(3 * fr(-5 + fr(2 * x2))));
}

// SVF_recalcFreq
function svfRecalc(v) {
	svG[v] = fastTan(fr(3.141592653589793 * svF[v] * kr));
}

// SVF_calcBlockZDF (also used by snare, cymbal and hihat: the reverb that would
// switch them to the cheap variant is disabled in the firmware)
function svfBlock(v, dst) {
	let ft = fType[v];
	if (ft == F_OFF || ft < F_LP || ft > F_OFF) return;
	let drive = svDrive[v];
	if (ft == F_LP2) {
		// alternative 2-pole lowpass (q in double, as written in the firmware)
		let fl = fr(svF[v] * kr * 2.2100000381469727);
		let q0 = 1 - svQ[v];
		let q = fr(q0 * 1.4 + q0 / (1.0 - fl));
		let a = svA[v];
		let b = svB[v];
		for (let i = 0; i < N; i++) {
			let x = softClip(fr(fr(SCR[dst + i] / 32767) * drive));
			a = fr(a + fr(fl * fr(fr(x - a) + fr(q * fr(a - b)))));
			if (a > 1) a = 1;
			else if (a < -1) a = -1;
			b = fr(b + fr(fl * fr(a - b)));
			if (b > 1) b = 1;
			else if (b < -1) b = -1;
			SCR[dst + i] = ssat(fr(b * 32767));
		}
		svA[v] = a;
		svB[v] = b;
		return;
	}
	// zero delay feedback state variable filter
	let g = svG[v];
	let R = svQ[v];
	if (svF[v] >= 0.44990000128746033) R = 1;
	let ff = fr(g * g);
	let s1 = svS1[v];
	let s2 = svS2[v];
	let g0 = fr(1 / fr(1 + fr(g * 2 * R)));
	let f1 = fr(ff * g0);
	let gg0 = fr(g * g0);
	let den = fr(f1 + 1);
	let blown = 0;
	scNan = 0;
	for (let i = 0; i < N; i++) {
		if (blown != 0) {
			// the float state overflowed: the firmware's samples are NaN, which the
			// Cortex-M7 turns into 0, until the next block resets the state
			SCR[dst + i] = 0;
			continue;
		}
		let x = softClip(fr(fr(SCR[dst + i] / 32767) * drive));
		let y1 = fr(fr(fr(fr(f1 * x) + s2) + fr(gg0 * s1)) / den);
		let xx = fr(x - y1);
		let cs1 = softClip(s1);
		let y0 = fr(fr(cs1 + fr(g * xx)) * g0);
		let ugb = fr(2 * R * y0);
		s1 = fr(cs1 + fr(2 * g * fr(xx - ugb)));
		s2 = fr(s2 + fr(2 * g * y0));
		let y = 0;
		if (ft == F_LP) y = fastTanh(y1);
		else if (ft == F_HP) y = fr(fr(x - ugb) - y1);
		else if (ft == F_BP) y = y0;
		else if (ft == F_UBP) y = ugb;
		else if (ft == F_NOTCH) y = fr(x - ugb);
		else y = fr(y1 - fr(fr(x - ugb) - y1));
		SCR[dst + i] = ssat(fr(y * 32767));
		if (scNan != 0) {
			blown = 1;
			SCR[dst + i] = 0;
		} else if (abs(s1) > FLT_MAX || abs(s2) > FLT_MAX) {
			blown = 1;
		}
	}
	if (blown != 0) {
		s1 = 0;
		s2 = 0;
	}
	svS1[v] = s1;
	svS2[v] = s2;
}

// calcDistBlock
// calcDistBlock (and the per-sample part of calcDistBlockFiltered)
function distBlock(v, dst) {
	let s = dShape[v];
	for (let i = 0; i < N; i++) SCR[dst + i] = shapeSample(SCR[dst + i], s);
}

function shapeSample(smp, s) {
	let x = fr(smp / 32767);
	x = fr(fr(fr(1 + s) * x) / fr(1 + fr(s * abs(x))));
	return i16(fr(x * 32767));
}

// mixer_decimateBlock
function srReduce(v, dst) {
	let inc = fr(decRate[v] * decRate[6]);
	for (let i = 0; i < N; i++) {
		decCnt[v] = fr(decCnt[v] + inc);
		if (decCnt[v] >= 1) {
			decCnt[v] = fr(decCnt[v] - 1);
			decHold[v] = SCR[dst + i];
		}
		SCR[dst + i] = decHold[v];
	}
}

// mixer_addDataToOutput (all output jacks count as plugged in)
function mixAdd(v, src) {
	let r = routing[v];
	let pl = panL[v];
	let pr = panR[v];
	if (r == 6) {
		for (let i = 0; i < N; i++) {
			let x = SCR[src + i];
			FXB[2 * i] = sat16(FXB[2 * i] + i16(fr(x * pl)));
			FXB[2 * i + 1] = sat16(FXB[2 * i + 1] + i16(fr(x * pr)));
		}
	} else if (r == 0 || r == 1) {
		let c = 128;
		if (r == 1) c = 0;
		for (let i = 0; i < N; i++) {
			let x = SCR[src + i];
			OUTB[c + i] = sat16(OUTB[c + i] + i16(fr(x * pl)));
			OUTB[c + 64 + i] = sat16(OUTB[c + 64 + i] + i16(fr(x * pr)));
		}
	} else {
		let c = 0;
		if (r == 2) c = 128;
		else if (r == 3) c = 192;
		else if (r == 5) c = 64;
		for (let i = 0; i < N; i++) OUTB[c + i] = sat16(OUTB[c + i] + SCR[src + i]);
	}
}

// ================================================================ LFOs and modulation
function lfoInc(freq, syncMode) {
	let lsr = fsr / N;
	if (syncMode <= 0 || syncMode >= 12) return f2u(fr(freq / fr(lsr)) * TWO32);
	let tf = 0;
	if (curBpm > 0) tf = fr(fr(curBpm / 60) / 4);
	let sc = 1;
	if (syncMode == 1) sc = 0.25;
	else if (syncMode == 2) sc = 0.5;
	else if (syncMode == 3) sc = 1;
	else if (syncMode == 4) sc = 2;
	else if (syncMode == 5) sc = 3;
	else if (syncMode == 6) sc = 4;
	else if (syncMode == 7) sc = 6;
	else if (syncMode == 8) sc = 8;
	else if (syncMode == 9) sc = 12;
	else if (syncMode == 10) sc = 16;
	else sc = 32;
	return f2u(fr(fr(tf * sc) / fr(lsr)) * TWO32);
}

function lfoSetFreq(l, f) {
	let x = fr(0.0078125 + fr(f * 0.9921875));
	lFreq[l] = fr(fr(fr(x * x) * x) * 200);
	lInc[l] = lfoInc(lFreq[l], lSync[l]);
}

// lfo_calc
function lfoCalc(l) {
	let old = lPhase[l];
	let ph = wrap32(old + f2u(fr(lInc[l])));
	lPhase[l] = ph;
	let w = lWave[l];
	if (w == 0) return fr(fr(SINE[floor(ph / 1048576)] / 32767) + 1) / 2;
	if (w == 1) return fr(1 - abs(fr(fr(fr(ph) / TWO32) * 2 - 1)));
	if (w == 2) return fr(fr(ph) / TWO32);
	if (w == 3) return fr(fr(4294967295 - ph) / TWO32);
	if (w == 4) {
		if (ph > 2147483647) return 1;
		return 0;
	}
	if (w == 5) {
		if (old > ph) lRnd[l] = fr(fr(rng32(16 + l)) / TWO32);
		return lRnd[l];
	}
	if (w == 6) {
		let x = fr(fr(ph) / TWO32);
		return fr(fr(x * x) * x);
	}
	if (w == 7) {
		let y = fr(fr(4294967295 - ph) / TWO32);
		return fr(fr(y * y) * y);
	}
	return 0;
}

function lfoRetrigger(voice) {
	for (let l = 0; l < 6; l++) {
		if (lRetrig[l] == voice + 1) lPhase[l] = lOffset[l];
	}
}

// modNode_updateValue: move a parameter around its set value by +-amount
function modUpdate(dest, amount, val) {
	if (HASPTR[dest] == 0) return;
	let nv = clamp01(fr(fr(P[dest] / 127) + fr(amount * fr(fr(val * 2) - 1))));
	applyLxrParam(dest, trunc(fr(nv * 127)), nv, 1);
}

// paramArray_setParameter: back to the value the parameter is set to
function resetParam(dest) {
	if (HASPTR[dest] == 0) return;
	applyLxrParam(dest, P[dest], fr(P[dest] / 127), 0);
}

function resetTargets() {
	for (let i = 0; i < 6; i++) resetParam(vmDest[i]);
	for (let i = 0; i < 6; i++) resetParam(lDest[i]);
}

function setVeloDest(i, target) {
	resetTargets();
	vmDest[i] = MT[target];
}

function setLfoDest(i, target) {
	resetTargets();
	lDest[i] = MT[target];
}

function veloMod(v, val) {
	vmLast[v] = val;
	modUpdate(vmDest[v], vmAmount[v], val);
}

// ================================================================ parameters
function waveVal(itg, flt, isMod, n) {
	if (isMod == 0) return itg;
	return min(n - 1, trunc(n * flt));
}

function setLxrParam(idx, val) {
	P[idx] = val;
	applyLxrParam(idx, val, fr(val / 127), 0);
}

// midiParser_ccHandler, by LXR parameter number. isMod: the call comes from an LFO or
// velocity modulator (flt is then the modulated value and itg = flt * 127).
function applyLxrParam(idx, itg, flt, isMod) {
	if (idx < 8) {
		if (idx == 1) oWave[0] = waveVal(itg, flt, isMod, 6);
		else if (idx == 2) oWave[2] = waveVal(itg, flt, isMod, 6);
		else if (idx == 3) oWave[4] = waveVal(itg, flt, isMod, 6);
		else if (idx == 4) oWave[6] = waveVal(itg, flt, isMod, 6);
		else if (idx == 6) oWave[8] = waveVal(itg, flt, isMod, 6);
		else if (idx == 7) oWave[11] = waveVal(itg, flt, isMod, 6);
	} else if (idx < 20) {
		// coarse / fine of the main oscillators
		let o = mainOsc(floor((idx - 8) / 2));
		if (idx - 8 - 2 * floor((idx - 8) / 2) == 0) oCoarse[o] = itg;
		else oFine[o] = itg;
		oscRecalc(o);
	} else if (idx < 27) {
		let o = 1;
		if (idx == 21) o = 3;
		else if (idx == 22) o = 5;
		else if (idx == 23) o = 9;
		else if (idx == 24) o = 10;
		else if (idx == 25) o = 12;
		else if (idx == 26) o = 13;
		oWave[o] = waveVal(itg, flt, isMod, 6);
	} else if (idx < 37) {
		if (idx == 27) oFreq[7] = fr(flt * 22000);
		else if (idx == 28) snMix = flt;
		else if (idx == 29) {
			oCoarse[9] = itg;
			oscRecalc(9);
		} else if (idx == 30) {
			oCoarse[10] = itg;
			oscRecalc(10);
		} else if (idx == 31) fmA1[4] = flt;
		else if (idx == 32) fmA2[4] = flt;
		else if (idx == 33) {
			oCoarse[12] = itg;
			oscRecalc(12);
		} else if (idx == 34) {
			oCoarse[13] = itg;
			oscRecalc(13);
		} else if (idx == 35) fmA1[5] = flt;
		else if (idx == 36) fmA2[5] = flt;
	} else if (idx < 43) {
		// SVF_directSetFilterValue(valueShaperF2F(f, FILTER_SHAPER))
		let v = idx - 37;
		svF[v] = fr(valueShaper(flt, -0.8999999761581421) * 0.44999998807907104);
		svfRecalc(v);
	} else if (idx < 49) {
		let v = idx - 43;
		svQ[v] = fr(1 - flt);
		if (svQ[v] < 0.10000000149011612) svQ[v] = 0.019999999552965164;
	} else if (idx < 60) {
		let k = idx - 49;
		let v = floor(k / 2);
		if (k - 2 * v == 0) aeAttack[v] = egTime(itg, K_ATTACK);
		else aeDecay[v] = egTime(itg, K_DECAY);
	} else if (idx < 62) {
		if (idx == 60) hhDecClosed = egTime(itg, K_DECAY);
		else hhDecOpen = egTime(itg, K_DECAY);
	} else if (idx < 68) {
		let v = idx - 62;
		let a = ((itg / 127) - 0.5) * 1.999;
		aeSlope[v] = 2 * a / (1 - a);
		aeInv[v] = -2 * a / (1 + a);
	} else if (idx < 70) {
		aeRepeat[idx - 65] = itg;
	} else if (idx < 74) {
		// DecayEg_calcTime
		let val = fr(itg / 127);
		let ret = fr(1 - fr(fr(fr(1 + K_PITCH) * val) / fr(1 + fr(K_PITCH * val)))) * 2;
		if (ret > 1) ret = 1;
		peDecay[idx - 70] = ret;
	} else if (idx < 78) {
		let val = fr(itg / 127);
		pAmt[idx - 74] = fr(fr(val * val) * 32);
	} else if (idx < 82) {
		// DecayEg_setSlope; at 127 the firmware divides by zero, here the curve just
		// gets as steep as at 126.99
		let a = min(0.9999, fr(fr(itg / 127) - 0.5) * 2);
		peSlope[idx - 78] = fr(2 * a / fr(1 - a));
	} else if (idx < 88) {
		let k = idx - 82;
		let v = floor(k / 2);
		if (k - 2 * v == 0) {
			fmAmt[v] = flt;
		} else {
			oCoarse[2 * v + 1] = itg;
			oscRecalc(2 * v + 1);
		}
	} else if (idx < 94) {
		vol[idx - 88] = flt;
	} else if (idx < 102) {
		if (idx < 97) pan[idx - 94] = itg;
		else if (idx > 98) pan[idx - 96] = itg;
	} else if (idx < 108) {
		// setDistortionShape
		let s = fr(flt - 0.0078125);
		dShape[idx - 102] = fr(fr(2 * s) / fr(1 - s));
	} else if (idx < 115) {
		decRate[idx - 108] = valueShaper(flt, -0.699999988079071);
	} else if (idx < 121) {
		lfoSetFreq(idx - 115, flt);
	} else if (idx < 127) {
		lAmount[idx - 121] = flt;
	} else if (idx < 128) {
		// bank change, not a sound parameter
	} else if (idx < 134) {
		svDrive[idx - 128] = fr(0.4000000059604645 + fr(fr(flt * flt) * 6));
	} else if (idx < 137) {
		mixOscs[idx - 134] = 0;
		if (itg != 0) mixOscs[idx - 134] = 1;
	} else if (idx < 143) {
		volMod[idx - 137] = 0;
		if (itg != 0) volMod[idx - 137] = 1;
	} else if (idx < 149) {
		vmAmount[idx - 143] = flt;
	} else if (idx < 155) {
		// velocity destination: handled by setVeloDest()
	} else if (idx < 161) {
		lWave[idx - 155] = waveVal(itg, flt, isMod, 8);
	} else if (idx < 173) {
		// LFO target voice/parameter: handled by setLfoDest()
	} else if (idx < 179) {
		if (isMod == 0) lRetrig[idx - 173] = itg;
		else lRetrig[idx - 173] = trunc(7 * flt);
	} else if (idx < 185) {
		let l = idx - 179;
		lSync[l] = itg;
		lInc[l] = lfoInc(lFreq[l], itg);
	} else if (idx < 191) {
		lOffset[idx - 185] = f2u(flt * TWO32);
	} else if (idx < 197) {
		let v = idx - 191;
		if (isMod == 0) {
			fType[v] = itg + 1;
		} else {
			let t = trunc(7 * flt + 1);
			if (t >= F_OFF) t = F_OFF - 1;
			fType[v] = t;
		}
	} else if (idx < 203) {
		trVol[idx - 197] = flt;
	} else if (idx < 209) {
		let w = itg;
		if (isMod != 0) w = min(11, trunc(12 * flt));
		if (w >= 14) w = 0;
		trWave[idx - 203] = w;
	} else if (idx < 215) {
		// 1.f + ((itg / 33.9f) - 0.75f), in float like the firmware
		trPitch[idx - 209] = fr(1 + fr(fr(itg / 33.900001525878906) - 0.75));
	} else if (idx < 221) {
		routing[idx - 215] = itg;
	} else if (idx < 228) {
		// unused
	} else if (idx < 234) {
		pwm[idx - 228] = flt;
	} else if (idx == 234) {
		fxType = itg;
		fxUpdate();
	} else if (idx == 235) {
		fxRouting = itg;
	} else if (idx == 236) {
		fxDryWet = fr(itg / 100);
	} else if (idx == 237) {
		dsType = itg;
	} else if (idx < 242) {
		fxP[idx - 238] = flt;
		fxUpdate();
	} else if (idx == 242) {
		compSetRatio(itg);
	} else if (idx == 243) {
		oWave[14] = itg;
	} else if (idx == 245) {
		dlType = itg;
	}
}

function bpmChanged() {
	for (let l = 0; l < 6; l++) lInc[l] = lfoInc(lFreq[l], lSync[l]);
}

// ================================================================ voices
function updatePan(v) {
	panL[v] = fr(sqrt(fr((127 - pan[v]) / 127)));
	panR[v] = fr(sqrt(fr(pan[v] / 127)));
}

// phase an oscillator restarts at, depending on its waveform
function startPhase(o, offset) {
	let w = oWave[o];
	if (w == W_SINE) return f2u(fr(1072693248 * offset));
	if (w >= 1 && w <= 3) return f2u(fr(1069547520 * offset));
	return 0;
}

function drumTrigger(v, vel, note) {
	lfoRetrigger(v);
	veloMod(v, fr(vel / 127));
	let offset = 1;
	if (trWave[v] == 1) offset = fr(offset - trVol[v]);
	let o = 2 * v;
	let w = oWave[o];
	if (w == W_SINE) oPhase[o] = f2u(fr(1024 + fr(1072692224 * offset)));
	else if (w >= 1 && w <= 3) oPhase[o] = f2u(fr(1069547520 * offset));
	else oPhase[o] = 0;
	oPhase[o + 1] = startPhase(o + 1, 1);
	oscBase(o, note);
	oscBase(o + 1, note);
	peValue[v] = 1;
	aeTrigger(v);
	velo[v] = fr(vel / 127);
	trPhase[v] = 0;
	snap[v] = 1;
	svS1[v] = 0;
	svS2[v] = 0;
	svA[v] = 0;
	svB[v] = 0;
	updatePan(v);
}

function snareTrigger(vel, note) {
	lfoRetrigger(3);
	veloMod(3, fr(vel / 127));
	let offset = 1;
	if (trWave[3] == 1) offset = fr(offset - trVol[3]);
	oPhase[6] = startPhase(6, offset);
	peValue[3] = 1;
	aeTrigger(3);
	velo[3] = fr(vel / 127);
	oscBase(6, note);
	trPhase[3] = 0;
	snap[3] = 1;
	updatePan(3);
}

// cymbal (v = 4) and hihat (v = 5, open = 0/1)
function metalTrigger(v, vel, isOpen, note) {
	lfoRetrigger(v);
	veloMod(v, fr(vel / 127));
	let offset = 1;
	if (trWave[v] == 1) offset = fr(offset - trVol[v]);
	let o = mainOsc(v);
	oPhase[o] = startPhase(o, offset);
	oPhase[o + 1] = 0;
	oPhase[o + 2] = 0;
	oscBase(o, note);
	oscBase(o + 1, note);
	oscBase(o + 2, note);
	if (v == 5) {
		if (isOpen != 0) aeDecay[5] = hhDecOpen;
		else aeDecay[5] = hhDecClosed;
	}
	aeTrigger(v);
	velo[v] = fr(vel / 127);
	trPhase[v] = 0;
	snap[v] = 1;
	updatePan(v);
}

function voiceTrigger(slot, vel, note) {
	if (slot < 3) drumTrigger(slot, vel, note);
	else if (slot == 3) snareTrigger(vel, note);
	else if (slot == 4) metalTrigger(4, vel, 0, note);
	else metalTrigger(5, vel, slot - 5, note);
}

function queueTrig(slot, code) {
	if (code <= 0) return;
	tPend[slot] = 1;
	tVel[slot] = code - 128 * floor(code / 128);
	let n = floor(code / 128);
	tNote[slot] = n - 128 * floor(n / 128);
}

// calcDrumVoiceAsync
function drumAsync(v) {
	let o = 2 * v;
	let eg = decayCalc(v);
	oPitch[o] = fr(1 + fr(eg * pAmt[v]));
	if (trWave[v] == 0) oPitch[o] = fr(oPitch[o] + fr(snapCalc(v, trPitch[v]) * trVol[v]));
	oFm[o] = fr(fmAmt[v] * eg);
	if (aeAttack[v] == 1 && (aeState[v] == EG_A || aeState[v] == EG_REPEAT)) {
		ampIn[v] = aeCalc(v);
		lastGain[v] = ampIn[v];
	} else {
		lastGain[v] = ampIn[v];
		ampIn[v] = aeCalc(v);
	}
	oscSetFreq(o);
	oscSetFreq(o + 1);
}

// calcDrumVoiceSyncBlock -> SCR[0..63]
function drumSync(v) {
	let o = 2 * v;
	oscBlock(o + 1, 64, fmAmt[v], pwm[v]);
	if (mixOscs[v] != 0) {
		oscBlock(o, 0, fr(1 - fmAmt[v]), pwm[v]);
		qaddBuf(0, 64);
	} else {
		oscFmBlock(o, 64, 0, 1, pwm[v]);
	}
	transBlock(v, 64);
	qaddBuf(0, 64);
	svfBlock(v, 0);
	// amp envelope, interpolated over the block (double maths in the firmware)
	let g1 = fr(ampIn[v]);
	let g0 = fr(lastGain[v]);
	let dg = fr(g1 - g0);
	for (let i = 0; i < N; i++) SCR[i] = i16(SCR[i] * (g0 + fr(i / 63) * dg));
	if (volMod[v] != 0) {
		for (let i = 0; i < N; i++) SCR[i] = i16(fr(SCR[i] * velo[v]));
	}
	// drive with smoothed amount, then smoothed volume
	for (let i = 0; i < N; i++) {
		driveB[v] = fr(driveB[v] + 0.009999999776482582 * fr(dShape[v] - driveB[v]));
		SCR[i] = shapeSample(SCR[i], driveB[v]);
	}
	for (let i = 0; i < N; i++) {
		mixVolB[v] = fr(mixVolB[v] + 0.009999999776482582 * fr(vol[v] - mixVolB[v]));
		fader[v] = fr(fader[v] + 0.009999999776482582 * fr(1 - fader[v]));
		SCR[i] = i16(fr(SCR[i] * fr(mixVolB[v] * fader[v])));
	}
}

function snareAsync() {
	let eg = decayCalc(3);
	oPitch[6] = fr(1 + fr(eg * pAmt[3]));
	egVol[3] = fr(aeCalc(3));
	if (trWave[3] == 0) oPitch[6] = fr(oPitch[6] + fr(snapCalc(3, trPitch[3]) * trVol[3]));
	oscSetFreq(6);
	oscSetFreq(7);
}

// Snare_calcSyncBlock -> SCR[0..63]
function snareSync() {
	noiseBlock(7, 0, 0.8999999761581421);
	svfBlock(3, 0);
	oscBlock(6, 64, fr(1 - snMix), pwm[3]);
	transBlock(3, 128);
	let cv = fr(vol[3] * egVol[3]);
	if (volMod[3] != 0) cv = fr(fr(vol[3] * velo[3]) * egVol[3]);
	for (let j = 0; j < N; j++) {
		let tmp = fr(fr(SCR[j] * snMix + SCR[64 + j]) + SCR[128 + j]);
		fader[3] = fr(fader[3] + 0.10000000149011612 * fr(1 - fader[3]));
		SCR[j] = i16(fr(fr(cv * tmp) * fader[3]));
	}
	distBlock(3, 0);
}

function metalAsync(v) {
	let o = mainOsc(v);
	egVol[v] = fr(aeCalc(v));
	if (trWave[v] == 0) oPitch[o] = fr(1 + fr(snapCalc(v, trPitch[v]) * trVol[v]));
	oscSetFreq(o);
	oscSetFreq(o + 1);
	oscSetFreq(o + 2);
}

// Cymbal_calcSyncBlock / HiHat_calcSyncBlock -> SCR[0..63]
function metalSync(v) {
	let o = mainOsc(v);
	oscBlock(o + 1, 64, fmA1[v], pwm[v]);
	oscBlock(o + 2, 128, fmA2[v], pwm[v]);
	qaddBuf(64, 128);
	let gain = 1;
	if (v == 5) gain = 0.5;
	oscFmBlock(o, 64, 0, gain, pwm[v]);
	svfBlock(v, 0);
	transBlock(v, 64);
	let cv = fr(vol[v] * egVol[v]);
	if (volMod[v] != 0) cv = fr(fr(vol[v] * velo[v]) * egVol[v]);
	qaddBuf(0, 64);
	for (let j = 0; j < N; j++) {
		fader[v] = fr(fader[v] + 0.10000000149011612 * fr(1 - fader[v]));
		SCR[j] = i16(fr(SCR[j] * fr(cv * fader[v])));
	}
	distBlock(v, 0);
}

// ================================================================ FX bus
function compSetRatio(r) {
	if (r == 1) cRatio = 0.5;
	else if (r == 2) cRatio = 1 / 3;
	else if (r == 3) cRatio = 0.25;
	else if (r == 4) cRatio = 1 / 6;
	else if (r == 5) cRatio = 0.125;
	else cRatio = 1;
}

// FxBus_updateParameter
function fxUpdate() {
	if (fxType == 1) {
		dsDrive = fxP[0];
		dsP1 = fxP[1];
		dsP2 = fxP[2];
		dsP3 = fxP[3];
	} else if (fxType == 2) {
		oFreq[14] = fr(fxP[0] * 880);
		oscSetFreq(14);
	} else if (fxType == 3) {
		// attack/release: time in ms to reach 63 %
		cAttack = fr(exp(-1000 / fr(fr(0.029999999329447746 + fr(fxP[0] * 100)) * fsr)));
		cRelease = fr(exp(-1000 / fr(fr(25 + fr(fxP[1] * 175)) * fsr)));
		cTresh = fr(-96 + fr(fxP[2] * 96));
		cMarkup = fr(1 + fxP[3] * 2);
	} else if (fxType == 4) {
		dlRange = fxP[1];
		delaySetTime(dlTime);
		delaySetTime(fxP[0]);
		dlToneR = fr(fxP[2] * fxP[2]);
		dlFb = fxP[3];
	}
}

// dry/wet mix of one sample, packed back into 16 bit like __PKHBT does
function fxDryWetMix(dry, wet) {
	return wrap16(dry + ssat(fr((wet - dry) * fxDryWet)));
}

function ecc83(x) {
	let inp = trunc(x);
	let s = sat16(inp);
	let itg = floor(s / 512) + 64;
	let frac = (inp - 512 * floor(inp / 512)) / 512;
	return ECC83[itg] + (ECC83[itg + 1] - ECC83[itg]) * frac;
}

function foldback(x) {
	x = fr(x);
	if (x > 1 || x < -1) {
		let a = fr(x - 1);
		x = fr(abs(abs(a - 4 * trunc(a / 4)) - 2) - 1);
	}
	return x;
}

// float diode(float in): 1N914 transfer curve
function diode(x) {
	x = fr(x);
	if (x < -1) x = -1;
	if (x > 1) x = 1;
	let index = fr(fr(x + 1) * 128);
	let itg = trunc(index);
	if (itg >= 256) return DIODE[256];
	let t = fr(index - itg);
	let a = DIODE[itg];
	return fr(t * DIODE[itg + 1] + fr(a - fr(t * a)));
}

// one channel of the "clip" (RAT) distortion
function rat(c, x, gain, coff) {
	let s = x / 32768 + dsLast[c] * dsP1 * 0.125;
	dsHp1[c] = dsHp1[c] + 0.64116641920131193922 * (s - dsHp1[c]);
	s = s - dsHp1[c];
	dsLp1[c] = dsLp1[c] + (1 - 0.1025353241628911807) * (s - dsLp1[c]);
	s = dsLp1[c];
	dsHp3[c] = dsHp3[c] + (1 - 0.99149556438154282898) * (s - dsHp3[c]);
	s = s - dsHp3[c];
	dsLp2[c] = dsLp2[c] + (1 - 0.93130041642945205043) * (s - dsLp2[c]);
	s = dsLp2[c] * gain;
	let diff = s - dsSlew[c];
	if (abs(diff) > 6.79655641141821477118) {
		if (diff > 0) diff = 6.79655641141821477118;
		else diff = -6.79655641141821477118;
	}
	dsSlew[c] = dsSlew[c] + diff;
	if (dsSlew[c] > 4.2) dsSlew[c] = 4.2;
	else if (dsSlew[c] < -4.2) dsSlew[c] = -4.2;
	dsLp3[c] = dsLp3[c] + coff * (diode(dsSlew[c]) - dsLp3[c]);
	dsLast[c] = dsLp3[c] * dsP3;
	return ssat(dsLast[c] * 32768);
}

function delayTimeSamples(cv) {
	let lowMin = fr(0.0006 * fsr);
	let lowMax = fr(0.02 * fsr);
	let lo = flerp(lowMin, lowMax, dlRange);
	let hiMax = 32767;
	if (dlType != 0) hiMax = fr(32767 * 0.47999998927116394);
	let hi = flerp(lowMax, hiMax, dlRange);
	return flerp(lo, hi, cv);
}

// interpolate(a, b, x) = a * (1 - x) + b * x in float
function flerp(a, b, x) {
	return fr(fr(a * fr(1 - x)) + fr(b * x));
}

// Delay_setDelayTime: retarget the read pointer with a 10 ms crossfade
function delaySetTime(t) {
	if (dlInterp <= 0) {
		dlTime = t;
		let offset = delayTimeSamples(fr(dlTime * dlRange));
		let offItg = trunc(offset);
		dlFracNew = fr(offset - offItg);
		let mask = 32768;
		if (dlType != 0) mask = 16384;
		let r = dlWrite - 1 - offItg;
		dlNew = r - mask * floor(r / mask);
		dlInterp = 1;
		dlStep = fr(1 / fr(fsr * 0.009999999776482582));
	} else {
		dlPendTime = t;
		dlPending = 1;
	}
}

function dlRead(pos, frac, region) {
	let mask = 32768;
	if (dlType != 0) mask = 16384;
	let p2 = pos + 1;
	p2 = p2 - mask * floor(p2 / mask);
	return i16(fr(flerp(DLB[region + pos], DLB[region + p2], frac) * 32767));
}

function dlAdvance(pos) {
	let mask = 32768;
	if (dlType != 0) mask = 16384;
	pos = pos + 1;
	return pos - mask * floor(pos / mask);
}

// adds the FX bus result to the output buffer(s) chosen by fxRouting
function fxProcess() {
	let ca = 128;
	let cb = 192;
	let stereo = 1;
	let r = fxRouting;
	if (r == 1) {
		ca = 0;
		cb = 64;
	} else if (r == 2) {
		stereo = 0;
	} else if (r == 3) {
		stereo = 0;
		ca = 192;
	} else if (r == 4) {
		stereo = 0;
		ca = 0;
	} else if (r == 5) {
		stereo = 0;
		ca = 64;
	}
	let t = fxType;
	if (t == 1) {
		let coff = 0.06537948995454451662 + dsP2 * 0.92410701734426630737;
		if (dsType == 0) {
			let om = fr((1.0 + 0.55 * dsP1) + 0.55 * dsP1);
			let dr = fr(1 + dsDrive * 4);
			if (stereo == 0) dr = fr(1 + dsDrive);
			for (let i = 0; i < N; i++) {
				let l = FXB[2 * i];
				let rr = FXB[2 * i + 1];
				dsLp3[0] = dsLp3[0] + coff * (ecc83(fr(l * dr)) - dsLp3[0]);
				let wl = ssat(dsLp3[0] * om * dsP3 * 32768);
				if (stereo != 0) {
					dsLp3[1] = dsLp3[1] + coff * (ecc83(fr(rr * dr)) - dsLp3[1]);
					let wr = ssat(dsLp3[1] * om * dsP3 * 32768);
					OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, wr));
				}
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wl));
			}
		} else if (dsType == 1) {
			let dr = fr(1 + dsDrive * 4);
			for (let i = 0; i < N; i++) {
				let l = FXB[2 * i];
				let rr = FXB[2 * i + 1];
				dsLp3[0] = dsLp3[0] + coff * (fr(fr((l / 32768) * dr) + dsP1) - dsLp3[0]);
				let wl = ssat(fr(fr(foldback(dsLp3[0]) * dsP3) * 32768));
				if (stereo != 0) {
					dsLp3[1] = dsLp3[1] + coff * (fr(fr((rr / 32768) * dr) + dsP1) - dsLp3[1]);
					let wr = ssat(fr(fr(foldback(dsLp3[1]) * dsP3) * 32768));
					OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, wr));
				}
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wl));
			}
		} else {
			let gain = 1 + fr(dsDrive * 2304);
			for (let i = 0; i < N; i++) {
				let l = FXB[2 * i];
				let rr = FXB[2 * i + 1];
				let wl = rat(0, l, gain, coff);
				if (stereo != 0) {
					let wr = rat(1, rr, gain, coff);
					OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, wr));
				}
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wl));
			}
		}
	} else if (t == 2) {
		oscBlock(14, 320, 1, 0.3);
		for (let i = 0; i < N; i++) {
			let l = FXB[2 * i];
			let rr = FXB[2 * i + 1];
			let m = SCR[320 + i];
			if (stereo != 0) {
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, floor(l * m / 65536)));
				OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, floor(rr * m / 65536)));
			} else {
				let wet = sat16(OUTB[ca + i] + floor(l * m / 65536));
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, wet));
			}
		}
	} else if (t == 3) {
		for (let i = 0; i < N; i++) {
			let l = FXB[2 * i];
			let rr = FXB[2 * i + 1];
			let x = l / 32768;
			if (stereo != 0) x = fr(0.5 * (l / 32768) + 0.5 * (rr / 32768));
			let peakdB = fr(log(fr(abs(x) + 1.0E-25))) * 8.6858896380650365530225783783321;
			let over = peakdB - cTresh;
			if (over < 0) over = 0;
			let coeff = cRelease;
			if (over > cEnv) coeff = cAttack;
			cEnv = over + coeff * (cEnv - over);
			let gr = fr(exp(fr(cEnv * (cRatio - 1) * 0.11512925464970228420089957273422)));
			if (stereo != 0) {
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, ssat(l * gr * cMarkup)));
				OUTB[cb + i] = sat16(OUTB[cb + i] + fxDryWetMix(rr, ssat(rr * gr * cMarkup)));
			} else {
				OUTB[ca + i] = sat16(OUTB[ca + i] + fxDryWetMix(l, i16(l * gr * cMarkup)));
			}
		}
	} else if (t == 4) {
		if (dlType == 0) delayNormal(ca, cb, stereo);
		else delayPingPong(ca, cb, stereo);
	} else {
		for (let i = 0; i < N; i++) {
			OUTB[ca + i] = sat16(OUTB[ca + i] + FXB[2 * i]);
			if (stereo != 0) OUTB[cb + i] = sat16(OUTB[cb + i] + FXB[2 * i + 1]);
		}
	}
}

// Delay_process (mono delay line fed with L+R)
function delayNormal(ca, cb, stereo) {
	for (let i = 0; i < N; i++) {
		let l = FXB[2 * i];
		let rr = FXB[2 * i + 1];
		let smp = 0;
		if (dlInterp <= 0) {
			dlT0 = dlRead(dlOld, dlFracOld, 0);
			dlOld = dlAdvance(dlOld);
			smp = dlT0;
			if (dlPending != 0) {
				dlPending = 0;
				delaySetTime(dlPendTime);
			}
		} else {
			dlT0 = dlRead(dlOld, dlFracOld, 0);
			dlOld = dlAdvance(dlOld);
			dlT1 = dlRead(dlNew, dlFracNew, 0);
			dlNew = dlAdvance(dlNew);
			smp = i16(fr(dlT0 * dlInterp) + dlT1 * (1.0 - dlInterp));
			dlInterp = fr(dlInterp - dlStep);
			if (dlInterp <= 0) {
				dlOld = dlNew;
				dlFracOld = dlFracNew;
			}
		}
		dlToneB = fr(dlToneB + dlToneR * fr(smp - dlToneB));
		smp = i16(dlToneB);
		let itg = sat16(sat16(l + rr) + i16(fr(smp * dlFb)));
		DLB[dlWrite] = f16(min(1, max(-1, fr(itg / 32767))));
		dlWrite = dlAdvance(dlWrite);
		OUTB[ca + i] = sat16(OUTB[ca + i] + sat16(l + ssat(fr((smp - l) * fxDryWet))));
		if (stereo != 0) OUTB[cb + i] = sat16(OUTB[cb + i] + sat16(rr + ssat(fr((smp - rr) * fxDryWet))));
	}
}

// Delay_processPingPong: the right line lives at FX_BUFFER[0..], the left one at
// FX_BUFFER[0x3fff..]; each output reads the other side's line
function delayPingPong(ca, cb, stereo) {
	for (let i = 0; i < N; i++) {
		let l = FXB[2 * i];
		let rr = FXB[2 * i + 1];
		let outL = 0;
		let outR = 0;
		if (dlInterp <= 0) {
			dlT0 = dlRead(dlOld, dlFracOld, 0);
			dlU0 = dlRead(dlOld, dlFracOld, 16383);
			dlOld = dlAdvance(dlOld);
			outL = dlT0;
			outR = dlU0;
			if (dlPending != 0) {
				dlPending = 0;
				delaySetTime(dlPendTime);
			}
		} else {
			dlT0 = dlRead(dlOld, dlFracOld, 0);
			dlU0 = dlRead(dlOld, dlFracOld, 16383);
			dlOld = dlAdvance(dlOld);
			dlT1 = dlRead(dlNew, dlFracNew, 0);
			dlU1 = dlRead(dlNew, dlFracNew, 16383);
			dlNew = dlAdvance(dlNew);
			outL = i16(fr(dlT0 * dlInterp) + dlT1 * (1.0 - dlInterp));
			outR = i16(fr(dlU0 * dlInterp) + dlU1 * (1.0 - dlInterp));
			dlInterp = fr(dlInterp - dlStep);
			if (dlInterp <= 0) {
				dlOld = dlNew;
				dlFracOld = dlFracNew;
			}
		}
		dlToneB = fr(dlToneB + dlToneR * fr(outL - dlToneB));
		outL = i16(dlToneB);
		dlTone2B = fr(dlTone2B + dlToneR * fr(outR - dlTone2B));
		outR = i16(dlTone2B);
		DLB[16383 + dlWrite] = f16(min(1, max(-1, fr(sat16(l + i16(fr(outL * dlFb))) / 32767))));
		DLB[dlWrite] = f16(min(1, max(-1, fr(sat16(rr + i16(fr(outR * dlFb))) / 32767))));
		dlWrite = dlAdvance(dlWrite);
		OUTB[ca + i] = sat16(OUTB[ca + i] + sat16(l + ssat(fr((outL - l) * fxDryWet))));
		if (stereo != 0) OUTB[cb + i] = sat16(OUTB[cb + i] + sat16(rr + ssat(fr((outR - rr) * fxDryWet))));
	}
}

// ================================================================ one 64-sample block
// mixer_calcNextSampleBlock, preceded by what happens between blocks on the hardware
// (parameter changes, then triggers)
function renderBlock() {
	scanParams();
	seqParams();
	seqTick();
	for (let s = 0; s < 7; s++) {
		if (tPend[s] != 0) {
			tPend[s] = 0;
			voiceTrigger(s, tVel[s], tNote[s]);
			tCount[s] = tCount[s] + 1;
			sqActive[s] = floor(0.06 * fsr / N) + 1;
		}
	}
	seqStatus();
	resetTargets();
	for (let i = 0; i < 6; i++) modUpdate(vmDest[i], vmAmount[i], vmLast[i]);
	for (let l = 0; l < 6; l++) modUpdate(lDest[l], lAmount[l], lfoCalc(l));
	for (let v = 0; v < 6; v++) svfRecalc(v);
	drumAsync(0);
	drumAsync(1);
	drumAsync(2);
	snareAsync();
	metalAsync(4);
	metalAsync(5);
	for (let i = 0; i < 256; i++) OUTB[i] = 0;
	for (let i = 0; i < 128; i++) FXB[i] = 0;
	for (let v = 0; v < 3; v++) {
		drumSync(v);
		srReduce(v, 0);
		mixAdd(v, 0);
	}
	snareSync();
	srReduce(3, 0);
	mixAdd(3, 0);
	metalSync(4);
	srReduce(4, 0);
	mixAdd(4, 0);
	metalSync(5);
	srReduce(5, 0);
	mixAdd(5, 0);
	fxProcess();
}

// ================================================================ step sequencer
function bit(mask, i) {
	return floor(mask / pow(2, i)) - 2 * floor(mask / pow(2, i + 1));
}

// in1: selected track (0-6) + 8 * running + 16 * mute bits
function seqControl(v) {
	let c = floor(v + 0.5);
	if (c < 0) return;
	sqSel = c - 8 * floor(c / 8);
	let run = floor(c / 8) - 2 * floor(c / 16);
	sqMutes = floor(c / 16);
	if (run != 0 && sqRun == 0) {
		sqGlobal = 0;
		sqTimer = 0;
	}
	sqRun = run;
}

function seqStepSamples() {
	return fsr * 60 / curBpm / 4;
}

// steps fire at the start of the block they fall into, like the firmware's sequencer
function seqTick() {
	if (sqRun == 0) return;
	sqTimer = sqTimer - N;
	if (sqTimer > 0) return;
	for (let t = 0; t < 7; t++) {
		let pos = sqGlobal - sqLen[t] * floor(sqGlobal / sqLen[t]);
		if (bit(sqOn[t], pos) != 0 && bit(sqMutes, t) == 0) {
			tPend[t] = 1;
			tNote[t] = 60;
			if (bit(sqAcc[t], pos) != 0) tVel[t] = sqAccVel;
			else tVel[t] = sqVel;
		}
	}
	// swing delays every second 16th by up to half a step
	let d = sqSwing / 127 * 0.5;
	if (sqGlobal - 2 * floor(sqGlobal / 2) == 0) d = -d;
	sqTimer = sqTimer + seqStepSamples() * (1 - d);
	sqGlobal = sqGlobal + 1;
}

// state for the Move UI, as integers below 2^24 so they survive 32-bit float signals
//   out5: step bits of the selected track    out6: its accent bits
//   out7: running + 2 * selected track + 16 * voice activity bits (7)
//   out8: lengths - 1 of tracks 1-4 (4 bits each), out9: of tracks 5-7
//   out10: last played step, modulo 720720 (divisible by every track length)
function seqStatus() {
	let act = 0;
	for (let s = 0; s < 7; s++) {
		if (sqActive[s] > 0) {
			sqActive[s] = sqActive[s] - 1;
			act = act + pow(2, s);
		}
	}
	let last = sqGlobal - 1;
	if (last < 0) last = 0;
	STAT[0] = sqOn[sqSel];
	STAT[1] = sqAcc[sqSel];
	STAT[2] = sqRun + 2 * sqSel + 16 * act;
	STAT[3] = (sqLen[0] - 1) + 16 * (sqLen[1] - 1) + 256 * (sqLen[2] - 1) + 4096 * (sqLen[3] - 1);
	STAT[4] = (sqLen[4] - 1) + 16 * (sqLen[5] - 1) + 256 * (sqLen[6] - 1);
	STAT[5] = last - 720720 * floor(last / 720720);
}

// ================================================================ setup
// power-on state of the firmware's DSP structs (the *_init() functions)
function engineInit() {
	for (let o = 0; o < 16; o++) {
		oFreq[o] = 440;
		oPitch[o] = 1;
		oWave[o] = 1;
		oCoarse[o] = 70;
		oFine[o] = 64;
	}
	for (let v = 0; v < 3; v++) {
		oWave[2 * v] = 1 + v;
		oPitch[2 * v] = 0;
		fmAmt[v] = 0.5;
		mixOscs[v] = 1;
		fType[v] = F_LP;
	}
	oWave[9] = W_SINE;
	oWave[10] = W_NOISE;
	oWave[12] = W_SINE;
	oWave[13] = W_NOISE;
	oFm[8] = 1;
	oFm[11] = 1;
	oFreq[14] = 100;
	oWave[14] = 3;
	oscSetFreq(14);
	for (let v = 0; v < 6; v++) {
		vol[v] = 0.8;
		volMod[v] = 1;
		pAmt[v] = 0.5;
		dShape[v] = 2 * (-0.0078125) / (1 + 0.0078125);
		trPitch[v] = 1;
		trVol[v] = 1;
		aeAttack[v] = 0.01;
		aeDecay[v] = 0.01;
		// slopeEg2_setSlope(eg, 0.5f) truncates 0.5 to 0
		let a = -0.5 * 1.999;
		aeSlope[v] = 2 * a / (1 - a);
		aeInv[v] = -2 * a / (1 + a);
		peDecay[v] = 0.01;
		svF[v] = 0.1125;
		svQ[v] = 0.9;
		svDrive[v] = 0.315;
		lInc[v] = 1;
		lFreq[v] = 1;
		fmA1[v] = 0.5;
		fmA2[v] = 0.5;
		decRate[v] = 1;
	}
	decRate[6] = 1;
	for (let k = 0; k < 24; k++) rngS[k] = wrap32(625341585 + k * 2654435769);
	for (let i = 0; i < 256; i++) P[i] = -1;
}

function dspsetup() {
	fsr = samplerate();
	kr = FS_REF / fsr;
	if (booted == 0) {
		tablesInit();
		engineInit();
		booted = 1;
	}
	// send every parameter again so rate dependent values follow the new sample rate
	for (let i = 0; i < 256; i++) P[i] = -1;
	blockPos = N;
}

