// unpack 3 x 16 bit per number
function fillSine(base, c: list) {
	for (let i = 0; i < c.length; i++) {
		let n = c[i];
		for (let k = 0; k < 3; k++) {
			let idx = base * 3 + i * 3 + k;
			let u = n - 65536 * floor(n / 65536);
			n = floor(n / 65536);
			if (idx < 4097) SINE[idx] = u - 32768;
		}
	}
}

function fillWave(base, c: list) {
	for (let i = 0; i < c.length; i++) {
		let n = c[i];
		for (let k = 0; k < 3; k++) {
			let idx = base * 3 + i * 3 + k;
			let u = n - 65536 * floor(n / 65536);
			n = floor(n / 65536);
			if (idx < 33795) WT[idx] = u - 32768;
		}
	}
}

// unpack 6 x 8 bit per number
function fillTransient(base, c: list) {
	for (let i = 0; i < c.length; i++) {
		let n = c[i];
		for (let k = 0; k < 6; k++) {
			let idx = base * 6 + i * 6 + k;
			let u = n - 256 * floor(n / 256);
			n = floor(n / 256);
			if (idx < 26460) TR[idx] = u - 128;
		}
	}
}

function fillList(which, c: list) {
	for (let i = 0; i < c.length; i++) {
		if (which == 0) ECC83[i] = c[i];
		else if (which == 1) DIODE[i] = c[i];
		else if (which == 2) NOTEF[i] = c[i];
		else if (which == 3) MT[i] = c[i];
		else HASPTR[c[i]] = 1;
	}
}

